  /* Prüfungsbauplan: Blockabdeckung, Formenmischung, Deckel auf MC und Richtig/Falsch */
  function blueprint(list, want, opts) {
    var o = opts || {};
    var cap = Math.floor(want * (o.mcShare || 0.5));
    var isMC = (e) => e.q.type === "mc" || e.q.type === "tf";
    var rest = list.slice();
    var out = [], seenBlocks = {};
    var take = (pred) => {
      for (let i = 0; i < rest.length; i += 1) {
        var e = rest[i];
        if (!pred(e)) continue;
        if (isMC(e) && out.filter(isMC).length >= cap) continue;
        out.push(e); rest.splice(i, 1);
        if (e.q.blockId) seenBlocks[e.q.blockId] = 1;
        return true;
      }
      return false;
    };
    // 1. jede Aufgabenform einmal, damit der Test nicht aus Ankreuzen besteht
    var forms = [];
    list.forEach((e) => { if (forms.indexOf(e.q.type) < 0) forms.push(e.q.type); });
    forms.filter((t) => t !== "mc" && t !== "tf").forEach((t) => {
      if (out.length < want) take((e) => e.q.type === t);
    });
    // 2. jeden Baustein mindestens einmal abdecken
    var blocks = [];
    list.forEach((e) => { if (e.q.blockId && blocks.indexOf(e.q.blockId) < 0) blocks.push(e.q.blockId); });
    blocks.forEach((b) => {
      if (out.length < want && !seenBlocks[b]) take((e) => e.q.blockId === b);
    });
    // 3. auffüllen, MC bleibt unter dem Deckel
    while (out.length < want && rest.length) {
      if (!take(() => true)) break;
    }
    // 4. Mindestlänge geht vor: reicht der Vorrat an anderen Formen nicht,
    //    wird der MC-Deckel überschritten statt einen zu kurzen Test zu bauen
    var min = o.min || 0;
    while (out.length < min && rest.length) {
      out.push(rest.shift());
    }
    out.mcShare = out.filter(isMC).length / Math.max(1, out.length);
    return out;
  }
  M.blueprint = blueprint;

  function startRun(el, mode, opt) {
    var cfg = MODES[mode] || MODES.daily; M.__runLabel = (opt && opt.label) || null; /* Iteration 5: Titel des gestarteten Tests für die Auswertung */
    // Formale Läufe fassen den Tageszähler erst bei der Abgabe an
    if (!cfg.nav) touchDay();
    var n = opt.n || (mode === "chapter" ? 99 : S.goal);
    var list = pool({ subject: opt.subject, chapterId: opt.chapterId, chapterIds: opt.chapterIds,
      onlyDue: mode === "review", onlyType: opt.onlyType });
    if (mode === "review" && !list.length) list = pool({ onlyWeak: true });
    /* r165: nie still mit einem anderen Fach auffüllen, wenn Fach oder Themen gewählt sind */
    var gefiltert = !!(opt.subject || opt.chapterId || (opt.chapterIds && opt.chapterIds.length));
    if (!list.length && gefiltert) { el.innerHTML = '<header class="vhead"><p class="eyebrow">Üben</p><h1>Zu diesem Thema gibt es noch keine Übungsaufgaben</h1><p class="vlead">Wir füllen die Runde nicht mit einem anderen Fach auf. Du kannst den Stoff nachlesen oder ein anderes Thema wählen.</p></header><div class="sk-schnell"><button type="button" data-sk-v="learn">Stoff nachlesen</button><button type="button" data-sk-v="practice">Anderes Thema wählen</button></div>'; el.querySelectorAll("[data-sk-v]").forEach(function (b) { b.onclick = function () { go(b.getAttribute("data-sk-v")); }; }); return; }
    if (!list.length) list = pool({});
    let qs;
    if (mode === "chapter") {
      qs = blueprint(list, Math.min(20, list.length), { mcShare: 0.5, min: Math.min(10, list.length) });
    } else if (mode === "quickQuiz") {
      var short = list.filter((e) => e.q.type !== "order" && e.q.type !== "keywords" && e.q.type !== "label");
      qs = blueprint(short.length >= 5 ? short : list, Math.min(opt.n || 5, list.length), { mcShare: 0.6 }); /* Iteration 18: angeforderte Anzahl (Fachtest 10, Kurzquiz 5) */
    } else {
      qs = pick(list, Math.min(n, list.length));
    }
    if (!qs.length) { el.innerHTML = `<div class="empty">Keine Aufgaben gefunden.</div>`; return; }
    R = { mode, cfg, qs, i: 0, ok: 0, combo: 0, maxCombo: 0, lives: cfg.lives, xp: 0, answers: [], responses: {}, flags: {}, done: false, t0: Date.now() };
    if (mode === "boss") {
      var b = M.FUN.bosses[opt.subject] || M.FUN.bosses.math;
      R.boss = b; R.bossHp = b.hp;
      R.qs = R.qs.slice(0, b.hp + 4);
      toast("<b>" + b.emoji + " " + M.esc(b.name) + "</b>" + M.esc(b.taunt), "boss");
    }
    renderRun(el);
  }

  function renderRun(el) {
    if (R.done) return renderResult(el);
    var q = R.qs[R.i].q; const c = R.qs[R.i].chapter;
    var pct = Math.round((R.i / R.qs.length) * 100);
    var graded = !!R.cfg.nav;
    R.flags = R.flags || {};
    var nav = graded ? `<nav class="qnav" aria-label="Aufgabenübersicht">
      ${R.qs.map((e, i) => {
        var r = R.responses[e.q.id];
        var done = !!(r && r.answered);
        return `<button class="qn${i === R.i ? " cur" : ""}${done ? " done" : ""}${R.flags[e.q.id] ? " flag" : ""}"
        data-jump="${i}" aria-label="Aufgabe ${i + 1}${done ? ", beantwortet" : ", offen"}${R.flags[e.q.id] ? ", markiert" : ""}"
        >${i + 1}</button>`;
      }).join("")}
      <span class="qnopen">${R.qs.filter((e) => !(R.responses[e.q.id] || {}).answered).length} offen</span></nav>` : "";
    el.innerHTML = `<div class="arena${R.cfg.workspace ? " workspace" : ""}${graded ? " graded" : ""}">
      ${graded && R.reviewStage ? `<div class="reviewbar">Alle Aufgaben durchlaufen.
        Prüfe deine Antworten über den Navigator und gib dann ab.</div>` : ""}
      ${graded ? `<div class="gradedhead"><span class="gtag">${esc(R.cfg.label)}</span>
        <span class="gnote">Antworten bleiben bis zur Abgabe änderbar. Keine Hinweise, Lösungen am Ende.</span></div>` : ""}
      ${nav}
      <div class="abar">
        ${R.cfg.lives ? `<span class="hearts">${[0, 1, 2].map((i) => `<span class="heart ${i < R.lives ? "on" : ""}">❤️</span>`).join("")}</span>` : ""}
        <span class="prog" role="progressbar" aria-label="Fortschritt der Runde" aria-valuenow="${pct}"><i style="width:${pct}%"></i></span>
        <span class="small muted num">${R.i + 1}/${R.qs.length}</span>
        ${!graded && R.combo >= 2 ? `<span class="combo ${R.combo >= 5 ? "big" : ""}">${R.combo}× ${esc(F.comboTitle(R.combo))}</span>` : ""}
        ${R.cfg.perQ ? `<span class="clock" id="clk">${R.cfg.perQ}</span>` : ""}
      </div>
      ${R.boss ? `<div class="bossbar"><span class="bemo">${R.boss.emoji}</span>
        <span class="bmeta"><b>${esc(R.boss.name)}</b>
        <span class="bhp" role="progressbar" aria-label="Lebenspunkte des Gegners"><i style="width:${Math.max(0, Math.round((R.bossHp / R.boss.hp) * 100))}%"></i></span></span>
        <span class="bnum num">${Math.max(0, R.bossHp)}/${R.boss.hp}</span></div>` : ""}
      <div class="qcard">
        <div class="qmeta"><span class="tag cy">${esc(M.SUBJECTS[c.subject].short)}</span>
          <span class="tag">${esc(c.title)}</span>
          ${q.role === "check" ? '<span class="tag volt">Verständnis</span>' : ""}
          ${q.fun ? '<span class="tag gold">Szenario</span>' : ""}
          <span class="tag gold">${"★".repeat(q.difficulty || 2)}</span></div>
        <div class="qp">${esc(q.prompt)}</div>
        <div id="qbody"></div>
        <div id="qfb" aria-live="polite"></div>
      </div>
      <div class="row" style="margin-top:12px;justify-content:space-between">
        <button class="btn ghost sm" id="quit">${graded ? "Test abgeben" : "Runde beenden"}</button>
        <span class="row">
          ${graded ? `<button class="btn sm${R.flags[(R.qs[R.i]||{}).q ? R.qs[R.i].q.id : "x"] ? " flagged" : ""}" id="flag">${R.flags[(R.qs[R.i]||{}).q ? R.qs[R.i].q.id : "x"] ? "Markiert" : "Markieren"}</button>` : ""}
          <button class="btn sm" id="skip">Überspringen →</button>
        </span>
      </div>
      <div class="keyhint">Tastatur: <b>1</b> bis <b>4</b> oder <b>A</b> bis <b>D</b> antworten, <b>S</b> sicher, <b>G</b> geraten, <b>Enter</b> weiter.</div>
      </div>`;
    $("#quit", el).onclick = () => {
      if (graded) {
        var open = R.qs.filter((e) => !(R.responses[e.q.id] || {}).answered).length;
        var flagged = Object.keys(R.flags).filter((k) => R.flags[k]).length;
        var msg = `Test jetzt abgeben?` + (open ? `\n\n${open} ${M.t("unit.tasks","Aufgaben")} sind noch offen.` : "\n\nAlle Aufgaben sind beantwortet.")
          + (flagged ? `\n${flagged} zur Nachkontrolle markiert.` : "");
        if (!M.bestaetigtOder($("#quit", el), msg, "Jetzt abgeben", "Weiter bearbeiten")) return;
      }
      finish(el);
    };
    var fl = $("#flag", el);
    if (fl) fl.onclick = () => { const id = (R.qs[R.i] || {}).q.id; R.flags[id] = !R.flags[id]; renderRun(el); };
    el.querySelectorAll("[data-jump]").forEach((b) => {
      b.onclick = () => { R.i = +b.dataset.jump; renderRun(el); };
    });
    $("#skip", el).onclick = () => {
      if (R.cfg.nav) {
        var q0 = R.qs[R.i] && R.qs[R.i].q;
        if (q0 && q0.id && !R.responses[q0.id]) R.responses[q0.id] = { correct: false, answered: false };
        R.i += 1;
        if (R.i >= R.qs.length) { R.i = R.qs.length - 1; R.reviewStage = true; }
        renderRun(el);
        return;
      } answer(el, false, null, true); };
    body(el, q);
    if (R.cfg.perQ) startClock(el);
    bindKeys(el);
  }

  var keyH = null;
  function bindKeys(el) {
    if (keyH) document.removeEventListener("keydown", keyH);
    keyH = function (e) {
      if (e.target && /INPUT|TEXTAREA/.test(e.target.tagName)) return;
      var cf = el.querySelector("[data-cf]");
      if (cf) {
        var k = String(e.key).toLowerCase();
        if (k === "s") { e.preventDefault(); el.querySelector('[data-cf="1"]').click(); return; }
        if (k === "g") { e.preventDefault(); el.querySelector('[data-cf="0"]').click(); return; }
        return;
      }
      var nx = $("#nx", el);
      if (nx && (e.key === "Enter" || e.key === " ")) { e.preventDefault(); nx.click(); return; }
      var ok = $("#ok", el);
      if (ok && !nx && e.key === "Enter") { e.preventDefault(); ok.click(); return; }
      var opts = [...el.querySelectorAll(".opt:not(:disabled)")];
      if (!opts.length) return;
      var i = -1;
      if (/^[1-6]$/.test(e.key)) i = +e.key - 1;
      var up = String(e.key).toUpperCase();
      if (/^[A-F]$/.test(up)) i = up.charCodeAt(0) - 65;
      if (i >= 0 && opts[i]) { e.preventDefault(); opts[i].click(); }
    };
    document.addEventListener("keydown", keyH);
  }
  function unbindKeys() { if (keyH) { document.removeEventListener("keydown", keyH); keyH = null; } }

  var clockT = null;
  function startClock(el) {
    clearInterval(clockT);
    var left = R.cfg.perQ;
    var node = $("#clk", el);
    clockT = setInterval(() => {
      left -= 1;
      if (!node || !node.isConnected) { clearInterval(clockT); return; }
      node.textContent = left;
      node.classList.toggle("low", left <= 10);
      if (left <= 0) { clearInterval(clockT); R.timedOut = true; answer(el, false, null, true); }
    }, 1000);
  }

  function shuffleOrder(q) {
    if (q.type === "tf") return q.options.map((_, i) => i);      // Richtig/Falsch bleibt in Reihenfolge
    var idx = q.options.map((_, i) => i);
    var seed = 0;
    for (let i = 0; i < q.id.length; i += 1) seed = (seed * 31 + q.id.charCodeAt(i)) % 99991;
    for (let i = idx.length - 1; i > 0; i -= 1) {
      seed = (seed * 1103515245 + 12345) % 2147483648;
      var j = seed % (i + 1);
      var t = idx[i]; idx[i] = idx[j]; idx[j] = t;
    }
    return idx;
  }
  function body(el, q) {
    var host = $("#qbody", el);
    if (M.QRENDER && M.QRENDER[q.type]) {
      M.renderQuestionBody(host, q, (ok, given) => answer(el, ok, given));
      return;
    }
    if (q.type === "mc" || q.type === "tf") {
      var order = shuffleOrder(q);
      host.innerHTML = `<div class="opts">${order.map((orig, i) =>
        `<button class="opt" data-i="${orig}"><span class="k">${"ABCDEF"[i]}</span><span>${esc(q.options[orig])}</span></button>`).join("")}</div>`;
      host.querySelectorAll(".opt").forEach((b) => { b.onclick = () => answer(el, +b.dataset.i === q.answer, +b.dataset.i); });
    } else if (q.type === "truefalse") {
      /* R155 QZ-02: «Trifft das zu?» mit zwei Knöpfen statt Freitext gegen «true» */
      var soll = q.answer === true || q.answer === "true";
      host.innerHTML = `<div class="opts">${[true, false].map((v, i) =>
        `<button class="opt" data-tf="${v}"><span class="k">${"AB"[i]}</span><span>${v ? "Richtig" : "Falsch"}</span></button>`).join("")}</div>`;
      host.querySelectorAll(".opt").forEach((b) => { b.onclick = () => { var v = b.dataset.tf === "true"; answer(el, v === soll, v); }; });
    } else if (q.type === "selection" && Array.isArray(q.answers) && (q.options || []).length) {
      /* R155 QZ-03: Auswahlaufgabe mit Lesetext; mehrere Antworten, dann prüfen */
      var pz = q.passage && Array.isArray(q.passage.zeilen) ? `<div class="r155-passage"><b>${esc(q.passage.titel || "Text")}</b>${q.passage.zeilen.map((z) => `<p>${esc(z)}</p>`).join("")}</div>` : "";
      host.innerHTML = `${pz}<p class="qhint">Mehrere Antworten möglich.</p><div class="opts">${q.options.map((o, i) =>
        `<button class="opt" data-i="${i}" aria-pressed="false"><span class="k">${"ABCDEF"[i]}</span><span>${esc(o)}</span></button>`).join("")}</div>
        <button class="btn go wide" id="ok" style="margin-top:10px">Auswahl prüfen</button>`;
      var wahl = {};
      host.querySelectorAll(".opt").forEach((b) => { b.onclick = () => { var i = +b.dataset.i; wahl[i] = !wahl[i]; b.setAttribute("aria-pressed", wahl[i] ? "true" : "false"); b.classList.toggle("on", !!wahl[i]); }; });
      $("#ok", el).onclick = () => { var ch = Object.keys(wahl).filter((k) => wahl[k]).map(Number).sort((a, b) => a - b), w = q.answers.map(Number).slice().sort((a, b) => a - b);
        answer(el, ch.length === w.length && ch.every((v, k) => v === w[k]), ch); };
    } else if (q.type === "numeric") {
      host.innerHTML = `<input class="ans" id="na" inputmode="decimal" placeholder="Zahl eingeben${q.unit ? " in " + esc(q.unit) : ""}">
        <button class="btn go wide" id="ok" style="margin-top:10px">Antwort prüfen</button>`;
      var go2 = () => {
        var zi = M.leseZahlInfo(q, $("#na", el).value), v = zi.v;   /* R157: typisierte Zahl mit Einheit */
        if (isNaN(v)) { $("#qfb", el).innerHTML = '<div class="fb r97-invalid">' + esc(zi.hinweis || "Bitte eine Zahl eingeben.") + '</div>'; return; }
        var ok = M.bewerteZahl(q, v);
        answer(el, ok, v);
      };
      $("#ok", el).onclick = go2;
      $("#na", el).onkeydown = (e) => { if (e.key === "Enter") go2(); };
    } else if (q.type === "order") {
      var items = q.items.slice();
      var order = items.map((_, i) => i).sort(() => Math.random() - 0.5);
      var draw = () => {
        host.innerHTML = `<div class="sortl">${order.map((oi, pos) => `<div class="sr">
          <span class="i">${pos + 1}</span><span class="t">${esc(items[oi])}</span>
          <span class="mv"><button data-u="${pos}" ${pos === 0 ? "disabled" : ""}>▲</button>
          <button data-d="${pos}" ${pos === order.length - 1 ? "disabled" : ""}>▼</button></span></div>`).join("")}</div>
          <button class="btn go wide" id="ok" style="margin-top:10px">Reihenfolge prüfen</button>`;
        host.querySelectorAll("[data-u]").forEach((b) => { b.onclick = () => { const p = +b.dataset.u; [order[p - 1], order[p]] = [order[p], order[p - 1]]; draw(); }; });
        host.querySelectorAll("[data-d]").forEach((b) => { b.onclick = () => { const p = +b.dataset.d; [order[p + 1], order[p]] = [order[p], order[p + 1]]; draw(); }; });
        $("#ok", el).onclick = () => answer(el, order.every((v, i) => v === i), order.slice());
      };
      draw();
    } else if (q.type === "keywords") {
      host.innerHTML = `<textarea class="ans" id="ta" rows="4" placeholder="In eigenen Worten erklären"></textarea>
        <button class="btn go wide" id="ok" style="margin-top:10px">Antwort prüfen</button>`;
      /* Selbstkontrolle statt Stichwortzählung. Ob ein Text ein Wort
         enthält, sagt nichts darüber, ob er richtig ist. Nach dem
         Schreiben sieht man Musterantwort und Kriterien und schätzt
         sich selbst ein. */
      $("#ok", el).textContent = "Mit Musterantwort vergleichen";
      $("#ok", el).onclick = () => {
        var t = String($("#ta", el).value);
        var kw = (q.keywords || []);
        var model = q.modelAnswer || q.explanation || "";
        var okb = $("#ok", el); if (okb) okb.remove();
        var box = document.createElement("div");
        box.className = "sc-box";
        box.innerHTML = '<p class="sc-h">Vergleiche selbst</p>'
          + (model ? '<p class="sc-model"><b>Musterantwort</b> ' + esc(model) + '</p>' : '')
          + (kw.length ? '<p class="sc-rh">Eine gute Antwort enthält</p><ul class="sc-rub">'
             + kw.map((k) => '<li>' + esc(k) + '</li>').join('') + '</ul>' : '')
          + '<div class="sc-act"><button class="btn go" data-sc="1">Hatte ich drin</button>'
          + '<button class="btn" data-sc="0">Noch nicht</button></div>';
        host.appendChild(box);
        box.querySelectorAll("[data-sc]").forEach((b) => {
          b.onclick = () => answer(el, b.dataset.sc === "1", t);
        });
      };
    } else {
      host.innerHTML = `<input class="ans" id="na" placeholder="Antwort eingeben">
        <button class="btn go wide" id="ok" style="margin-top:10px">Antwort prüfen</button>`;
      $("#ok", el).onclick = () => {
        var t = String($("#na", el).value).trim().toLowerCase();
        var acc = (q.accepted || [q.answer]).map((a) => String(a).toLowerCase());
        answer(el, acc.some((a) => a === t), t);
      };
    }
  }

  function answer(el, ok, given, skipped) {
    clearInterval(clockT);
    var entry = R.qs[R.i]; const q = entry.q;
    var wasTimeout = R.timedOut; R.timedOut = false;
    R.pendingGrade = { id: q.id, ok: ok };
    if (!R.cfg.confid || skipped) recordAnswer(q.id, ok, ok && !skipped, R.mode);
    if (R.cfg.nav) {
      // Formale Modi: genau eine Antwort je Frage-ID, erneutes Antworten ersetzt sie
      R.responses[q.id] = { value: given === undefined ? null : given, correct: !!ok,
        answered: true, answeredAt: Date.now(),
        chapter: entry.chapter.id, subject: entry.chapter.subject };
    } else {
      R.answers.push({ id: q.id, ok, chapter: entry.chapter.id, subject: entry.chapter.subject });
    }
    var formal = !!R.cfg.nav;   // Kurzquiz, Kapiteltest, Fachtest, Prüfung
    if (ok) {
      if (!formal) R.ok += 1;   // formale Auswertung zählt ausschliesslich responses
      if (!formal) {
        R.combo += 1; R.maxCombo = Math.max(R.maxCombo, R.combo);
        var mult = 1 + Math.min(1, Math.floor(R.combo / 3) * 0.25);
        var gained = Math.round(R.cfg.xp * mult);
        R.xp += gained; addXP(gained);
        S.maxCombo = Math.max(S.maxCombo || 0, R.maxCombo);
      }
      if (R.boss) R.bossHp -= 1;
    } else {
      if (!formal) R.combo = 0;
      if (R.cfg.lives) R.lives -= 1;
      // Nur im Lernmodus kehren falsche Aufgaben zurück. Die Prüfung bleibt endlich.
      if (R.cfg.requeue) R.qs.push(entry);
    }
    // Formale Läufe schreiben nichts, bevor abgegeben wurde
    if (!formal) { save(); flushLevelUp(); }
    if (!R.cfg.reveal) { advance(el); return; }
    // reveal
    var host = $("#qbody", el);
    host.querySelectorAll(".opt").forEach((x, k) => {
      x.disabled = true;
      var o = x.dataset.i != null && x.dataset.i !== "" ? +x.dataset.i : k;   /* R155 QZ-01: gemischte Reihenfolge */
      if (Array.isArray(q.answers) ? q.answers.indexOf(o) >= 0 : (q.type === "truefalse" ? (x.dataset.tf === String(q.answer === true || q.answer === "true")) : o === q.answer)) x.classList.add("right");
      else if (Array.isArray(given) ? given.indexOf(o) >= 0 : (q.type === "truefalse" ? x.dataset.tf === String(given) : o === given)) x.classList.add("wrong");
    });
    host.querySelectorAll("button:not(.opt)").forEach((b) => { b.disabled = true; });
    host.querySelectorAll(".sr").forEach((r, i) => r.classList.add(i === 0 || true ? (ok ? "right" : "bad") : ""));
    var sol = solutionOf(q);
    var mrFF = R.mrFF || 0; R.mrFF = ok ? 0 : mrFF + 1;
    $("#qfb", el).innerHTML = `<div class="fb ${ok ? "ok" : "no"}">
      ${M.arenaMr ? M.arenaMr(entry.chapter.id, { ok: ok, skipped: skipped, combo: ok && R.combo > 0 && R.combo % 5 === 0, serie: R.combo, falschFolge: mrFF, boss: !!R.boss }) : ""}
      <span class="v">${ok ? `${praise()} <span class="xpfly">+${Math.round(R.cfg.xp * (1 + Math.min(1, Math.floor(R.combo / 3) * 0.25)))} XP</span>`
        : skipped ? esc(F.pick(wasTimeout ? F.timeout : F.skipped)) : esc(F.pick(F.consol))}</span>
      ${M.warumArena ? M.warumArena(q, given, ok) : ""}
      ${esc(q.explanation || "")}
      ${!ok && sol ? `<span class="ref">Richtige Antwort: ${esc(sol)}</span>` : ""}
      ${M.loesungsweg ? M.loesungsweg(q) : ""}
      <span class="ref">Nachlesen: ${q.ref ? esc(q.ref) + " in " : ""}„${esc(entry.chapter.title)}“</span>
      ${!ok && R.cfg.requeue ? `<span class="ref">Diese Aufgabe kommt in dieser Runde nochmals.</span>` : ""}</div>
      ${R.cfg.confid && !skipped ? `<div class="confid">
        <span>Wie sicher war das?</span>
        <button class="btn sm" data-cf="1">Sicher gewusst <kbd>S</kbd></button>
        <button class="btn sm" data-cf="0">Eher geraten <kbd>G</kbd></button>
      </div>` : `<button class="btn go wide" id="nx" style="margin-top:12px">Weiter →</button>`}`;
    if (window.mnReaktion && window.mnReaktion.beleben) window.mnReaktion.beleben($("#qfb", el));
    if (R.cfg.confid && !skipped) {
      el.querySelectorAll("[data-cf]").forEach((b) => {
        b.onclick = () => {
          var sure = b.dataset.cf === "1";
          recordAnswer(R.pendingGrade.id, R.pendingGrade.ok, R.pendingGrade.ok && sure, R.mode);
          save();
          if (!sure && R.pendingGrade.ok && R.cfg.requeue) R.qs.push(entry);
          advance(el);
        };
      });
    } else {
      $("#nx", el).onclick = () => advance(el);
      $("#nx", el).focus();
    }
    renderHUD();
  }
  var F = M.FUN;
  var praise = () => F.praiseFor(R ? R.combo : 1);
  function solutionOf(q) {
    if (M.solutionText) { const t = M.solutionText(q); if (t) return t; }
    if (q.type === "mc" || q.type === "tf") return q.options[q.answer];
    if (q.type === "numeric") return `${q.answer}${q.unit ? " " + q.unit : ""}`;
    if (q.type === "order") return (q.items || []).join(" → ");
    if (q.type === "keywords") return q.modelAnswer || "";
    return String(q.answer ?? "");
  }
  function advance(el) {
    R.i += 1;
    if (R.cfg.lives && R.lives <= 0) return finish(el);
    if (R.i >= R.qs.length) {
      if (R.cfg.nav) {                       // formale Tests: erst prüfen, dann abgeben
        R.i = R.qs.length - 1;
        R.reviewStage = true;
        return renderRun(el);
      }
      return finish(el);
    }
    renderRun(el);
  }
  function finish(el) {
    clearInterval(clockT); unbindKeys();
    R.done = true;
    var graded = !!R.cfg.nav;
    var answeredIds = R.qs.map((e) => e.q.id).filter((id) => (R.responses[id] || {}).answered);
    var total = graded ? R.qs.length : (R.answers.length || 1);
    var open = graded ? R.qs.length - answeredIds.length : 0;
    if (graded && !R.committed) {               // genau einmal festschreiben
      R.committed = true;
      touchDay();                               // Tageszähler erst jetzt
      S.testHistory = S.testHistory || {};
      answeredIds.forEach((id) => {
        var h = S.testHistory[id] = S.testHistory[id] || { n: 0, ok: 0 };
        h.n += 1; if (R.responses[id].correct) h.ok += 1;
      });
      S.testRuns = S.testRuns || [];
      S.testRuns.push({ mode: R.mode, at: Date.now(), total: R.qs.length,
        ok: answeredIds.filter((id) => R.responses[id].correct).length,
        open: R.qs.length - answeredIds.length,
        seconds: Math.round((Date.now() - R.t0) / 1000) });
      save();
    }
    var okCount = graded ? answeredIds.filter((k) => R.responses[k].correct).length : R.ok;
    var pct = Math.round(((graded ? okCount : R.ok) / total) * 100);
    S.runs.unshift({ mode: R.mode, pct, total, ok: R.ok, lives: R.lives, xp: R.xp, at: Date.now() });
    S.runs = S.runs.slice(0, 60);
    if (R.mode === "chapter" && R.qs[0]) {
      var cid = R.qs[0].chapter.id;
      var st = S.chapters[cid] || (S.chapters[cid] = { read: true, best: 0, runs: 0 });
      st.best = Math.max(st.best, pct / 100); st.runs += 1;
    }
    var fresh = checkBadges();
    save(); renderHUD();
    renderResult(el, fresh);
    try{ window.dispatchEvent(new CustomEvent("Stoffknacker:testfertig",{detail:{mode:R.mode,pct:pct,el:el}})); }catch(e){} /* R72: Signal fuer das Feier-Modul */
  }
  function bindReview(el) {
    el.querySelectorAll("[data-revgo]").forEach((b) => {
      b.onclick = () => go("read", b.dataset.revgo);
    });
  }
  function renderResult(el, fresh) {
    var runIsGame = M.isGame(R.mode);
    var graded = !!R.cfg.nav;
    var answeredIds = R.qs.map((e) => e.q.id).filter((id) => (R.responses[id] || {}).answered);
    var total = graded ? R.qs.length : (R.answers.length || 1);
    var open = graded ? R.qs.length - answeredIds.length : 0;
    var okCount = graded ? answeredIds.filter((k) => R.responses[k].correct).length : R.ok;
    var pct = Math.round(((graded ? okCount : R.ok) / total) * 100);
    var resultQ0 = R.qs && R.qs[0] ? R.qs[0] : null;
    var resultSubject = resultQ0 && (resultQ0.chapter || resultQ0.c) ? (resultQ0.chapter || resultQ0.c).subject : null;
    var resultMentor = M.MentorsCompact
      ? M.MentorsCompact.html({ subject: resultSubject, context: "result", stableKey: String(R.t0 || Date.now()), pose: pct >= 80 ? "completion" : pct >= 50 ? "neutral" : "incorrect", variant: "result" })
      : "";
    var vd = M.FUN.verdict(pct, R.mode);
    var bossWon = R.boss && R.bossHp <= 0;
    var grade6 = Math.max(1, Math.min(6, Math.round((1 + 5 * (pct / 100)) * 2) / 2));
    var col = pct >= 80 ? "var(--volt)" : pct >= 60 ? "var(--gold)" : "var(--hot)";
    var wrongBy = {};
    if (graded) {
      R.qs.forEach((e) => { const r = R.responses[e.q.id];
        if (!r || !r.answered || !r.correct) wrongBy[e.chapter.id] = (wrongBy[e.chapter.id] || 0) + 1; });
    } else {
      R.answers.filter((a) => !a.ok).forEach((a) => { wrongBy[a.chapter] = (wrongBy[a.chapter] || 0) + 1; });
    }
    var weak = Object.entries(wrongBy).sort((a, b) => b[1] - a[1]).slice(0, 4);
    /* Nachbesprechung: jede falsche und jede offene Aufgabe mit Lösung */
    var reviewItems = graded ? R.qs.map((e) => {
      var r = R.responses[e.q.id] || {};
      if (r.answered && r.correct) return null;
      return { e: e, given: r.answered ? r.value : null, open: !r.answered };
    }).filter(Boolean) : [];
    var reviewHTML = reviewItems.length ? `
      <h2 class="secline">Was schiefgelaufen ist</h2>
      <p class="modeintro">${reviewItems.filter((x) => x.open).length} offen,
        ${reviewItems.filter((x) => !x.open).length} falsch beantwortet.
        Jede Aufgabe mit richtiger Lösung und Begründung.</p>
      <div class="reviewlist">${reviewItems.map((x, i) => {
        var q = x.e.q, ch = x.e.chapter;
        var sol = M.solutionText ? M.solutionText(q) : String(q.answer);
        var mine = x.open ? null
          : (q.options && typeof x.given === "number" ? q.options[x.given] : x.given);
        return `<article class="revitem">
          <p class="revno">${i + 1} · ${esc(M.tc("subject:" + ch.subject, "label", M.SUBJECTS[ch.subject].label))} · ${esc(ch.title)}
            ${x.open ? `<span class="revtag open">nicht beantwortet</span>`
              : `<span class="revtag wrong">falsch</span>`}</p>
          <p class="revq">${esc(q.prompt)}</p>
          ${mine !== null && mine !== undefined && String(mine).length
            ? `<p class="revmine"><span>Deine Antwort</span>${esc(String(mine))}</p>` : ""}
          <p class="revsol"><span>Richtig</span>${esc(sol)}</p>
          ${q.explanation ? `<p class="revwhy">${esc(q.explanation)}</p>` : ""}
          ${M.loesungsweg ? M.loesungsweg(q) : ""}
          <button class="lnk" data-revgo="${esc(ch.id)}">Zum Kapitel ${esc(ch.title)} →</button>
        </article>`;
      }).join("")}</div>` : (graded ? `<p class="note">Alles richtig. Nichts nachzubesprechen.</p>` : "");
    el.innerHTML = `<div class="arena"><div class="card result">${resultMentor}
      <div class="small muted">${esc(M.__runLabel || R.cfg.label)}</div>
      ${R.boss ? `<div class="bossres ${bossWon ? "won" : "lost"}"><span class="bemo">${R.boss.emoji}</span>
        <b>${bossWon ? "Duell gewonnen" : "Duell verloren"}</b>
        <span>${esc(bossWon ? R.boss.win : R.boss.lose)}</span></div>` : ""}
      <div class="big" style="color:${col}">${pct}%</div>
      <div class="verdict"><b>${esc(vd[0])}</b> ${esc(vd[1])}</div>
      <div class="grade" style="background:${col === "var(--volt)" ? "var(--volt-w)" : col === "var(--gold)" ? "var(--gold-w)" : "var(--hot-w)"};color:${col}">
        ${runIsGame ? `Spielergebnis · ${R.ok} von ${total} richtig`
          : graded ? `${okCount} von ${total} richtig${open ? " · " + open + " unbeantwortet" : ""}`
          : `Note etwa ${grade6.toFixed(1)} · ${R.ok} von ${total} richtig`}</div>
      ${graded ? `<div class="grid g3" style="margin-top:14px">
        <div class="stat"><b>${okCount}</b><span>richtig</span></div>
        <div class="stat"><b>${total - okCount - open}</b><span>falsch</span></div>
        <div class="stat"><b>${open}</b><span>unbeantwortet</span></div>
      </div>
      ${open ? `<p class="note" style="text-align:left">Die Note wird erst ausgewiesen, wenn alle
        ${total} ${M.t("unit.tasks","Aufgaben")} beantwortet sind. Offen zählen als nicht bestanden.</p>`
        : `<div class="grade" style="margin-top:10px">Note etwa ${grade6.toFixed(1)}</div>`}`
      : `<div class="grid g3" style="margin-top:14px">
        <div class="stat"><b>+${R.xp}</b><span>XP verdient</span></div>
        <div class="stat"><b>${R.maxCombo}×</b><span>längste Combo</span></div>
        <div class="stat"><b>${Math.round((Date.now() - R.t0) / 60000)}</b><span>Minuten</span></div>
      </div>`}
      ${fresh && fresh.length ? `<div class="badges">${fresh.map((b) => `<div class="badge earned"><span class="e">${b.e}</span><span class="n">${esc(b.n)}</span></div>`).join("")}</div>
        <div class="small" style="color:var(--gold)">Neues Abzeichen freigeschaltet</div>` : ""}
      ${weak.length ? `<div style="text-align:left;margin-top:16px">
        <h4 style="font-size:12.5px;color:var(--tx3);margin-bottom:8px">DARAN SOLLTEST DU ARBEITEN</h4>
        ${weak.map(([cid, n]) => { const c = M.chapter(cid); return c ? `<button class="chap" data-open="${esc(cid)}">
          <span class="st part">${n}</span><span class="m"><b>${esc(c.title)}</b><span>${esc(M.tc("subject:" + c.subject, "label", M.SUBJECTS[c.subject].label))} · ${n} Fehler</span></span></button>` : ""; }).join("")}
      </div>` : ""}
      <div class="row" style="margin-top:16px;justify-content:center">
        <button class="btn go" id="again">Noch eine Runde</button>
        <button class="btn ghost" id="home2">Zur Übersicht</button>
      </div>
      ${reviewHTML}
    </div></div>`;
    el.querySelectorAll("[data-open]").forEach((b) => { b.onclick = () => go("read", b.dataset.open); });
    bindReview(el);
    $("#again", el).onclick = () => { const m = R.mode; R = null; startRun(el, m === "chapter" ? "daily" : m, {}); };
    $("#home2", el).onclick = () => { R = null; go("home"); };
  }

  /* ---- progress ---- */
  var cardState = null;
  views.cards = (el, arg) => {
    var opts = (arg && typeof arg === "object") ? arg : {};
    var startDeck = () => {
      var all = M.buildCards(opts);
      var deck = M.pickCards(all, Math.min(opts.n || 20, all.length), S, isDue);
      cardState = { deck, i: 0, known: 0, again: 0, deferred: 0, xp: 0, flips: 0, opts,
        session: "c" + Date.now().toString(36) + Math.random().toString(36).slice(2, 7), committed: -1, events: [] };
      M.renderCards(el, cardState, api);
    };
    var api = {
      answer: (card, known, flipped) => {
        touchDay();
        if (flipped) cardState.flips += 1;
        if (!card.term) grade(card.id, known, known && !flipped);
        else {
          var it = item(card.id);
          it.n += 1; it.ok = known ? it.ok + 1 : 0;
          it.due = M.dayKey(M.addDays(new Date(), known ? Math.min(30, it.ok * 3) : 0));
        }
        if (known) { cardState.known += 1; cardState.xp += flipped ? 4 : 8; addXP(flipped ? 4 : 8); }
        else cardState.again += 1;
        save(); renderHUD(); flushLevelUp();
      },
      /* Für später: keine Wertung, kein Fortschritt, die Runde bleibt gleich gross (MN-059) */
      defer: (card) => {
        cardState.deferred += 1;
        S.cardsLater = S.cardsLater || {};
        S.cardsLater[card.id] = M.dayKey();
        save();
      },
      restart: startDeck,
    };
    if (!cardState || arg) startDeck();
    else M.renderCards(el, cardState, api);
  };

  views.cover = (el) => { M.renderCoverage(el, S); };

  function homeStats() {
    var entries = M.activeQuestionEntries ? M.activeQuestionEntries() : M.allQuestions();
    var due = entries.filter((x) => S.items[x.q.id] && isDue(x.q.id)).length;
    var mastered = entries.filter((x) => S.items[x.q.id] && S.items[x.q.id].ok >= 3).length;
    var weak = null;
    var chapters = M.activeChapters ? M.activeChapters() : M.chapters;
    chapters.forEach((c) => {
      var ids = chQuestions(c).map((q) => q.id);
      var errs = ids.filter((id) => S.items[id] && S.items[id].n > S.items[id].ok).length;
      if (errs >= 2 && (!weak || errs > weak.errors)) weak = { id: c.id, title: c.title, errors: errs };
    });
    return { due, mastery: Math.round((mastered / Math.max(1, entries.length)) * 100),
      daysToExam: M.targetDate() ? M.daysUntil(M.targetDate()) : 0, streak: S.streak || 0, weakChapter: weak };
  }

  function wirePicks(el) {
    el.querySelectorAll("[data-act]").forEach((b) => {
      b.onclick = () => {
        var act = b.dataset.act;
        var arg = null;
        try { arg = b.dataset.arg ? JSON.parse(b.dataset.arg) : null; } catch (e) {}
        if (act === "run") go("train", arg);
        else if (act === "read") go("read", arg);
        else if (act === "cards") go("cards", { n: 20 });
        else if (act === "chaptertest") go("chaptertest");
        else if (act === "duel") go("train", { mode: "boss", subject: "physics", n: 14 });
        else if (act === "hunt") go("train", { mode: "errorHunt", n: 5, onlyType: "finderror" });
        else go(act);
      };
    });
  }
  views.practice = (el) => { M.renderPractice(el, S, homeStats()); wirePicks(el); };
  views.test = (el) => { M.renderTest(el, S, homeStats()); wirePicks(el); };
  views.repeat = (el) => { M.renderRepeat(el, S, homeStats()); wirePicks(el); };
  views.games = (el) => { M.renderGames(el); wirePicks(el); };
  /* Batch A (UX): jede Ansicht gehört zu genau einem der vier Hauptpunkte. */
