  function heatmap() {
    var byDay = {};
    (M.activeQuestionEntries ? M.activeQuestionEntries() : M.allQuestions()).forEach((x) => {
      var it = S.items[x.q.id];
      if (!it || !it.due) return;
      byDay[it.due] = (byDay[it.due] || 0) + 1;
    });
    var today = new Date();
    var cells = [];
    var max = 1;
    for (let k = 0; k < 56; k += 1) {
      var d = M.addDays(today, k);
      var key = M.dayKey(d);
      var n = byDay[key] || 0;
      if (n > max) max = n;
      cells.push({ key, n, d, overdue: false });
    }
    var over = 0;
    Object.keys(byDay).forEach((k) => { if (k < M.dayKey(today)) over += byDay[k]; });
    var weeks = [];
    for (let w = 0; w < 8; w += 1) weeks.push(cells.slice(w * 7, w * 7 + 7));
    var lvl = (n) => (n === 0 ? 0 : n <= max * 0.25 ? 1 : n <= max * 0.5 ? 2 : n <= max * 0.75 ? 3 : 4);
    return `<h3 class="heath">${M.t("stat.due","Fällige Wiederholungen")}, nächste acht Wochen</h3>
      ${over ? `<p class="heatover">${over} ${M.t("unit.tasks","Aufgaben")} sind bereits überfällig.</p>` : ""}
      <div class="heat" role="img" aria-label="Kalender der fälligen Wiederholungen für acht Wochen">
        ${weeks.map((wk, wi) => `<div class="heatcol">
          <span class="heatlbl">${wi === 0 ? "diese" : "+" + wi}</span>
          ${wk.map((c) => `<i class="heatcell l${lvl(c.n)}" title="${c.d.getDate()}.${c.d.getMonth() + 1}.: ${c.n} ${M.t("unit.due","fällig")}"></i>`).join("")}
        </div>`).join("")}
      </div>
      <p class="heatlegend"><span>wenig</span>
        <i class="heatcell l0"></i><i class="heatcell l1"></i><i class="heatcell l2"></i>
        <i class="heatcell l3"></i><i class="heatcell l4"></i><span>viel</span></p>
      <p class="heatnote">Jede Spalte ist eine Woche, jedes Feld ein Tag. Wo sich Felder häufen,
        lohnt sich eine kurze Runde vorher.</p>`;
  }

  views.stats = (el) => {
    var days = [];
    for (let k = 13; k >= 0; k -= 1) {
      var d = M.addDays(new Date(), -k);
      var key = M.dayKey(d);
      days.push([String(d.getDate()), S.days[key] || 0]);
    }
    var subs = (M.activeSubjectOrder ? M.activeSubjectOrder() : M.SUBJECT_ORDER).map((s2) => {
      var ids = [];
      CH.filter((c) => c.subject === s2 && (!M.chapterAllowed || M.chapterAllowed(c.id))).forEach((c) => chQuestions(c).forEach((q) => ids.push(q.id)));
      var mast = ids.filter((id) => S.items[id] && S.items[id].ok >= 3).length;
      return [M.SUBJECTS[s2].short, Math.round((mast / Math.max(1, ids.length)) * 100)];
    });
    var errs = [];
    CH.filter((c) => !M.chapterAllowed || M.chapterAllowed(c.id)).forEach((c) => {
      var ids = chQuestions(c).map((q) => q.id);
      var e = ids.filter((id) => S.items[id] && S.items[id].n > S.items[id].ok).length;
      if (e) errs.push({ title: c.title, e: e, id: c.id });
    });
    errs.sort((a, b) => b.e - a.e);
    var due = (M.activeQuestionEntries ? M.activeQuestionEntries() : M.allQuestions()).filter((x) => S.items[x.q.id] && isDue(x.q.id)).length;
    el.innerHTML = M.viewHead("progress") +
      `<div class="statusrow" style="margin-bottom:28px">
        <div><b>${Math.round(subs.reduce((a, x) => a + x[1], 0) / Math.max(1, subs.length))}%</b><span>Beherrschung im Schnitt</span></div>
        <div><b>${due}</b><span>fällige Wiederholungen</span></div>
        <div><b>${S.streak || 0}</b><span>Tage Serie</span></div>
        <div><b>${S.xp || 0}</b><span>XP, misst nur Aktivität</span></div>
      </div>
      <div class="vizstack">
        ${M.Viz.barChart({ title: "Aktivität der letzten 14 Tage", yTitle: "XP am Tag", xTitle: "Tag",
          data: days, caption: "XP zeigt, wie viel du getan hast, nicht wie sicher du bist." })}
        ${M.Viz.barChart({ title: "Beherrschung je Fach", yTitle: "Prozent sicher", xTitle: "Fach", max: 100,
          data: subs, caption: "Sicher heisst: die Aufgabe wurde dreimal richtig beantwortet." })}
      </div>
      <h2 class="secline">Wann was fällig wird</h2>
      <div class="card heatwrap">${heatmap()}</div>
      ${errs.length ? `<h2 class="secline">Wo Fehler wiederkehren</h2>
      <div class="errlist">${errs.slice(0, 6).map((x) => `<button class="errrow" data-go="${esc(x.id)}">
        <span class="errn">${x.e}</span><span>${esc(x.title)}</span><span class="errcta">Kapitel öffnen</span></button>`).join("")}</div>` : ""}`;
    el.querySelectorAll("[data-go]").forEach((b) => { b.onclick = () => go("read", b.dataset.go); });
  };

