    r.push({name:"Six visible qualifications",pass:M.PROGRAMS.filter(function(p){return p.active!==false;}).length===6,detail:"6"});
    r.push({name:"Three static interface languages",pass:M.availableLocales().length===3,detail:"DE/EN/FR"});
